@Entity @Table(name="video_practice_attempts") @Getter @Setter @NoArgsConstructor public class VideoPracticeAttemptJpaEntity { @Id private UUID id; @Column(name="user_id",nullable=false) private UUID userId; @Column(name="video_id",nullable=false) private UUID videoId; @Enumerated(EnumType.STRING) @Column(name="practice_type",nullable=false) private PracticeType practiceType; @Enumerated(EnumType.STRING) @Column(nullable=false) private PracticeStatus status; @Column(name="started_at",nullable=false) private Instant startedAt; @Column(name="completed_at") private Instant completedAt; @JdbcTypeCode(SqlTypes.JSON) @Column(name="result_snapshot",columnDefinition="JSONB") private String resultSnapshot; }
